ALTER TABLE "youtube_discovery_candidates" DROP CONSTRAINT "youtube_discovery_candidates_safe_text_check";--> statement-breakpoint
ALTER TABLE "youtube_discovery_candidates" ADD CONSTRAINT "youtube_discovery_candidates_safe_text_check" CHECK (("title" IS NULL OR (char_length("title") <= 200 AND "title" !~ '[\x00-\x1F\x7F]')) AND ("description" IS NULL OR (char_length("description") <= 1000 AND "description" !~ '[\x00-\x1F\x7F]')) AND ("channel_name" IS NULL OR (char_length("channel_name") <= 160 AND "channel_name" !~ '[\x00-\x1F\x7F]')));--> statement-breakpoint
ALTER TABLE "youtube_discovery_candidates" DROP CONSTRAINT "youtube_discovery_candidates_tags_check";--> statement-breakpoint
ALTER TABLE "youtube_discovery_candidates" ADD CONSTRAINT "youtube_discovery_candidates_tags_check" CHECK ("tags" IS NULL OR (cardinality("tags") <= 20 AND char_length(array_to_string("tags", '')) <= 1600 AND array_to_string("tags", '') !~ '[\x00-\x1F\x7F]' AND array_to_string("tags", chr(31)) !~ ('(^|' || chr(31) || ')[^' || chr(31) || ']{81}')));
